func rtgJvmJvmPackageJvmPoolByteString(pool *rtgJvmJvmPackageJvmConstantPool, value []byte) int {
	raw := string(value)
	key := "B" + raw
	if found := rtgJvmJvmPackageJvmPoolFind(pool, key); found != 0 {
		return found
	}
	utfKey := "b" + raw
	utfIndex := rtgJvmJvmPackageJvmPoolFind(pool, utfKey)
	if utfIndex == 0 {
		encoded := make([]byte, 0, len(value)*2)
		for i := 0; i < len(value); i++ {
			ch := int(value[i])
			if ch == 0 {
				encoded = append(encoded, 0xc0, 0x80)
			} else if ch < 0x80 {
				encoded = append(encoded, byte(ch))
			} else {
				encoded = append(encoded, byte(0xc0|(ch>>6)), byte(0x80|(ch&63)))
			}
		}
		entry := []byte{1}
		entry = rtgJvmJvmPackageJvmBE16(entry, len(encoded))
		entry = append(entry, encoded...)
		utfIndex = rtgJvmJvmPackageJvmPoolAdd(pool, utfKey, entry)
	}
	entry := []byte{8}
	entry = rtgJvmJvmPackageJvmBE16(entry, utfIndex)
	return rtgJvmJvmPackageJvmPoolAdd(pool, key, entry)
}
